Bool PathfindLayer::DoBoundsOverlap(const IRegion2D *region)
{
	// True when any of the layer's areas, grown by 10 cells each way, overlaps the region.
	for (PolygonTrigger *area = m_areas; area != NULL; area = area->m_nextLayerArea)
	{
		IRegion2D bounds;
		area->getBounds(&bounds);
		if (region->hi.x + 10 > bounds.lo.x && region->hi.y + 10 > bounds.lo.y
			&& region->lo.x - 10 < bounds.hi.x && region->lo.y - 10 < bounds.hi.y)
			return true;
	}
	return false;
}

